import random


def wuerfeln(seed):
    return random.Random(seed).randint(1, 6), seed + 1


def ansage(echte, mindestens):
    if echte > mindestens:
        return echte
    else:
        return min(mindestens + 1, 6)


def runde(state):
    echte, seed = wuerfeln(state["seed"])
    genannt = ansage(echte, state["mindestens"])
    if genannt < 6:
        return {"seed": seed, "mindestens": genannt, "punkte": state["punkte"],
                "am_zug": 1 - state["am_zug"], "vorbei": False}
    p = state["punkte"]
    if genannt == echte:
        neue_punkte = (p[0] + 1, p[1]) if state["am_zug"] == 0 else (p[0], p[1] + 1)
    else:
        neue_punkte = (p[0] + 1, p[1]) if state["am_zug"] == 1 else (p[0], p[1] + 1)
    return {"seed": seed, "mindestens": 0, "punkte": neue_punkte,
            "am_zug": 1 - state["am_zug"], "vorbei": True}


