def spiele(strategie_a, strategie_b, runden, historie=()):
    if runden == 0:
        return reduce(lambda stand, zug: (stand[0] + auszahlung[zug][0],
                                          stand[1] + auszahlung[zug][1]),
                      historie,
                      (0, 0))
    a = strategie_a(tuple(map(lambda zug: zug[1], historie)))
    b = strategie_b(tuple(map(lambda zug: zug[0], historie)))
    return spiele(strategie_a, strategie_b, runden - 1, historie + ((a, b), ))

